

import typing

from ..core import enum

T_Result = typing.TypeVar("T_Result")


class CreateMessageRequestRole(enum.StrEnum):
    """
    The role of the entity that is creating the message. Allowed values include:
    - `user`: Indicates the message is sent by an actual user and should be used in most cases to represent user-generated messages.
    - `assistant`: Indicates the message is generated by the assistant. Use this value to insert messages from the assistant into the conversation.
    """

    USER = "user"
    ASSISTANT = "assistant"

    def visit(self, user: typing.Callable[[], T_Result], assistant: typing.Callable[[], T_Result]) -> T_Result:
        if self is CreateMessageRequestRole.USER:
            return user()
        if self is CreateMessageRequestRole.ASSISTANT:
            return assistant()
